fn fibonacci(n: usize) -> Vec<i32> {
    // Since n is at least 2, we can safely initialize with first two numbers
    let mut result = Vec::with_capacity(n);
    
    // Base cases
    result.push(0);  // F(0)
    result.push(1);  // F(1)
    
    // Generate remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}